# -*- coding: utf-8 -*-
"""docs/2.3-内容设计文档.docx —— 按 game-docs-and-sheets-inventory.md 2.3 写。

清单要求：每个事件的设计意图 / 参数进 Excel / 通过标准与难度曲线 /
内容产出方式（手写还是规则生成）。
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "2.3-内容设计文档.docx")


def main():
    doc = k.new_doc("2.3 内容设计文档 · v0.1 · 2026-11-04")
    k.title(
        doc,
        "电竞选手模拟器 · 内容设计",
        "关卡/内容设计文档（事件即关卡）· v0.1 · 2026-11-04",
    )

    k.note(
        doc,
        "这个游戏没有关卡，**事件就是关卡**：一周最多一条，一屏文字，2–3 个选项，选完立刻给后果。"
        "本文写「一条事件为什么长这样」；具体数值进 P1 事件库 xlsx 与 src/config.ts，代码结构见 src/types.ts。",
    )

    # ---------------- 一 ----------------
    k.h1(doc, "一", "这条事件想让玩家做什么决定")
    k.para(
        doc,
        "每一周玩家已经用三个行动格做了资源取舍，事件是**第二层决策**：在已经花掉的体力之外，"
        "再问一次「你是哪种人」。所以一条合格的事件必须满足三条：",
    )
    k.table(
        doc,
        ["#", "要求", "不合格的例子"],
        [
            ["1", "有代价", "两个选项都涨属性、只是多少不同"],
            ["2", "有画面", "「你训练更努力了，属性 +1」——没有场景，玩家记不住"],
            ["3", "选完能说出「我刚才赌了一把」", "纯数值增减，没有风险/人情/立场"],
        ],
        [1.0, 8.4, 6.6],
        size=9,
    )

    # ---------------- 二 ----------------
    k.h1(doc, "二", "一条事件由什么组成")
    k.table(
        doc,
        ["字段", "含义", "约束"],
        [
            ["id", "唯一编号（E01 / F01 …）", "不可复用"],
            ["kind", "match 比赛 / life 生活 / special 特殊", "决定是否走比赛胜负公式"],
            ["phase", "growth 成长 / peak 巅峰 / decline 衰退 / any", "决定它只在生涯哪一段出现"],
            ["year / week", "写死年份或周次（决赛、邀请函）", "有它就不走随机池，必触发"],
            ["text", "事件正文", "**硬上限 50 字**（config.events.textMaxLength）"],
            ["options", "2–3 个选项", "每个选项自带成败文案与后果"],
            ["once", "true = 一局只出一次；false = 可重复进池", "一次性事件用完即退场"],
            ["weight", "进池权重（常规 10、特殊 1）", "权重越高越容易被抽到"],
            ["requires", "附加条件（如人气 > 50 才出现）", "不写就是无条件"],
            ["filler", "true = 空池兜底事件", "只在没别的事件可抽时出现"],
        ],
        [2.4, 7.6, 6.0],
        size=9,
    )
    k.para(
        doc,
        "选项的后果只有四种落点：**属性加减 / 教练信任 / 钱 / 人气**，外加一个「标记」（flags）用于结局尾注。"
        "不做「加一个新状态」——加状态就要改存档结构与界面。",
    )

    # ---------------- 三 ----------------
    k.h1(doc, "三", "哪一条会在这一周出现（抽取顺序）")
    k.table(
        doc,
        ["序", "规则", "说明"],
        [
            ["1", "有写死年份/周次的必触发事件（决赛、签约邀请函）", "符合就出，不走随机"],
            ["2", "按生涯阶段分桶，比赛事件只在本周有比赛时进池", "成长/巅峰/衰退各有自己的池"],
            ["3", "去掉已触发过的 `once` 事件", "一次性事件不退场会让池子越来越小"],
            ["4", "按 `requires` 过滤", "条件不满足的不进池"],
            ["5", "按 weight 加权抽一条", "常规 10、特殊 1"],
            ["6", "池空 → 抽兜底池（filler）", "兜底也只有 2 条"],
            ["7", "还空 → **这周没有事件**", "所以内容量直接决定「空周转」"],
        ],
        [1.0, 9.4, 5.6],
        size=9,
        caption="表 3-1　对应 src/core/events.ts 的 drawEvent；第 7 步是当前最大的内容风险",
    )

    # ---------------- 四 ----------------
    k.h1(doc, "四", "现在一共有多少内容")
    k.table(
        doc,
        ["来源", "事件", "选项", "在哪儿"],
        [
            ["**已进代码**", "**4 条**（另 2 条兜底）", "12", "src/data/events.ts"],
            ["梗驱动初审", "22 条", "55", "P1-事件库-梗驱动-初审.xlsx"],
            ["人物梗初审", "12 条", "36", "P1-事件库-人物梗-初审.xlsx"],
            ["第一轮（已被上面取代）", "7 条", "17", "P1-事件库-第一轮.xlsx"],
            ["上限（1.3 定）", "60 条", "≤3/条", "docs/1.3-范围与预算表.docx"],
        ],
        [4.2, 4.4, 3.4, 5.0],
        size=9,
        caption="表 4-1　表里有 34 条，游戏里只有 4 条——这是当前最大的「文档与实现」落差",
    )
    k.para(
        doc,
        "素材底稿：`lol-memes/LOL赛场梗表.xlsx` 520 条、`LOL人物梗表.xlsx` 1000 条。"
        "但**梗是素材，不是内容**：1000 条里绝大多数是外号或一句话，单独成不了事件，需要「场景 + 代价」才成形。",
    )

    # ---------------- 五 ----------------
    k.h1(doc, "五", "重复怎么办")
    k.table(
        doc,
        ["情况", "规则", "体验后果"],
        [
            ["同一局里第二次抽到", "`once: true` 的事件不再进池", "不会重复看同一段"],
            ["可重复事件（`once: false`）", "每次回池，靠 weight 控制频率", "目前只有比赛事件是可重复的"],
            ["池子被抽空", "只剩兜底事件，再抽空就「本周无事件」", "240 周里会出现大量空周"],
            ["跨局重复", "每局重新开始，事件库不变", "第二局开始会背答案——这是内容量的硬上限"],
        ],
        [4.0, 7.6, 4.4],
        size=9,
    )

    # ---------------- 六 ----------------
    k.h1(doc, "六", "内容怎么产出（手写还是规则生成）")
    k.para(
        doc,
        "**结论：手写文本 + 规则复用后果。** 纯手写 100 条事件是项目坟场；纯规则生成读起来像机器写的。"
        "折中做法是文本人工写，后果只从固定的四种落点里组合。",
    )
    k.table(
        doc,
        ["步", "做什么", "产出", "判据"],
        [
            ["1 选梗", "从梗表里挑「有场景」的梗（能落到某个具体时刻）", "梗 → 场景一句话", "能说出画面：谁、在哪、什么时候"],
            ["2 写正文", "50 字内，只写局面，不写解释", "事件正文", "读完知道「我现在必须选」"],
            ["3 配选项", "2–3 个，各自有明确立场（激进/保守/人情）", "选项 + 成败文案", "两个选项不能只差数值"],
            ["4 落后果", "从 属性/信任/钱/人气 里选 2 个以内", "Consequence", "不新增状态字段"],
            ["5 进表", "写进 xlsx（含状态列：草稿/待验证/已确认）", "事件库 xlsx", "有状态列，否则表会烂"],
            ["6 入库", "转成 TS、跑测试、检查正文长度", "src/data/events.ts", "npm test 全过 + 正文 ≤50 字"],
        ],
        [2.0, 7.4, 3.8, 4.8],
        size=9,
    )

    # ---------------- 七 ----------------
    k.h1(doc, "七", "通过标准（一条事件算合格）")
    k.table(
        doc,
        ["#", "标准", "怎么验"],
        [
            ["1", "正文 ≤ 50 字", "数一遍；超了砍形容词"],
            ["2", "选项 2–3 个，每个 ≤ 4 字", "按钮宽度与拇指都靠这个"],
            ["3", "每个选项都有成功与失败文案", "失败文案必须带梗，不能只写「失败了」"],
            ["4", "后果落点 ≤ 2 种", "多了玩家记不住因果"],
            ["5", "至少一个选项有真实风险（掷骰）", "全是必然成功 = 假选择"],
            ["6", "能进结局尾注的，写 flags", "结局要靠它念出「当年那个选择」"],
            ["7", "在对应阶段里读得通", "衰退期的事件不能还在写「新人」"],
        ],
        [1.0, 7.0, 8.0],
        size=9,
    )

    # ---------------- 八 ----------------
    k.h1(doc, "八", "难度曲线：三个阶段各该给什么")
    k.table(
        doc,
        ["阶段", "年份", "事件的赌注", "后果量级（相对象限）"],
        [
            ["成长", "1–2 年", "路人期：要不要去试训、要不要回怼弹幕、要不要继续播", "小：信任 ±2~5，人气 ±1~5"],
            ["巅峰", "3–6 年", "队内位置、决赛前夜、伤病与代言、要不要背锅", "中：信任 ±5~10，人气 ±5~15"],
            ["衰退", "7–8 年", "退役时机、带新人、直播转型、最后一舞", "大：信任与荣誉定型，属性开始下滑"],
        ],
        [2.4, 2.4, 7.2, 4.0],
        size=9,
        caption="表 8-1　难度不是「更难赢」，是「后果越来越不可逆」",
    )

    # ---------------- 九 ----------------
    k.h1(doc, "九", "已知问题")
    k.table(
        doc,
        ["#", "问题", "证据"],
        [
            ["1", "表里有 34 条，代码里只有 4 条", "src/data/events.ts 只有 E01–E04"],
            ["2", "240 周里会出现大量「本周无事件」", "一次性事件抽完后池子为空，兜底只有 2 条"],
            ["3", "第二局开始会背答案", "事件库固定，没有随机变体"],
            ["4", "梗表 1000 条多数不能单独成事", "多数是外号／口头禅，缺场景"],
            ["5", "事件后果只落在四个字段", "想加「粉丝好感」「队内关系」就得改存档与界面"],
        ],
        [1.0, 8.0, 7.0],
        size=9,
    )

    k.note(
        doc,
        "下一步（我的建议，等你定）：按「梗驱动 22 条 → 人物梗 12 条」的顺序入库，每 10 条跑一次全量测试；"
        "入库完成前不要再写新事件，否则表会先于代码膨胀。",
    )

    doc.save(OUT)
    print("saved", OUT)


if __name__ == "__main__":
    main()
